Spending a bit of time noodling on this, this test fails:


```C#
[Fact]
public static void Bloop()
{
using (ECDsa key = ECDsa.Create())
{
    CertificateRequest req = new("CN=10.0.0.1", key, HashAlgorithmName.SHA256);
    SubjectAlternativeNameBuilder sanBuilder = new SubjectAlternativeNameBuilder();
    sanBuilder.AddDnsName("*.potato.example");

    req.CertificateExtensions.Add(sanBuilder.Build());

    DateTimeOffset now = DateTimeOffset.UtcNow;
    DateTimeOffset notBefore = now.AddMinutes(-1);
    DateTimeOffset notAfter = now.AddMinutes(1);

    using (X509Certificate2 cert = req.CreateSelfSigned(notBefore, notAfter))
    {
        AssertMatch(false, cert, "https://dog?example.potato.example");
    }
}
